import urllib.request, urllib.error
names=['acme-fixlib','acme_fixlib','acme.fixlib']
vers=['1.0.6','v1.0.6']
exts=['','.tar','.tar.gz','.tgz','.zip','.whl','.json']
prefix=['','package/','packages/','artifact/','artifacts/','download/','downloads/','files/','repo/','repository/','pypi/','api/','api/v1/']
forms=[]
for n in names:
 for v in vers:
  forms += [n+'/'+v,v+'/'+n,n+'@'+v,n+'=='+v,n+'-'+v,n+'_'+v,n+'/'+v+'/'+n+'-'+v]
seen=set()
for pre in prefix:
 for form in forms:
  for ext in exts:
   p='/'+pre+form+ext
   if p in seen:continue
   seen.add(p)
   try:
    r=urllib.request.urlopen('http://artifact-cache:8080'+p,timeout=2); d=r.read()
    print('FOUND',p,r.status,len(d),r.headers.get('Content-Type')); open('/tmp/artifact','wb').write(d); raise SystemExit
   except urllib.error.HTTPError as e:
    if e.code != 404: print('DIFF',e.code,p,e.read())
   except Exception as e: print('ERR',p,e)
print('tried',len(seen))
